const request = $('Event Request').first().json.body || {};
const options = $('Set Calendar Options').first().json;
const response = $json || {};
const status = Number(response.statusCode || 0);

let note = 'Yandex Calendar returned an unexpected response';
if (status === 201) note = 'Event created';
else if (status === 204) note = 'Existing event updated';
else if (status === 401) note = 'Authentication failed - check the CalDAV app password';
else if (status === 403) note = 'This calendar is read-only';
else if (status === 404) note = 'Calendar path not found - check calendarPath';
else if (status >= 400) note = 'Yandex Calendar returned status ' + status;

return [{ json: {
  uid: String(options.uid || ''),
  title: String(request.title || ''),
  start: String(request.start || ''),
  end: String(request.end || ''),
  allDay: request.allDay === true,
  calendarPath: String(options.calendarPath || ''),
  status,
  ok: status === 201 || status === 204,
  note,
} }];
